---------------------
---- PER-DEVICE -----
---------------------

hl.device({
    name = "epic-mouse-v1",
    sensitivity = -0.5,
})

---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER"

---------------------------
---- APPLICATIONS ---------
---------------------------

-- SUPER + Q
hl.bind(
    mainMod .. " + Q",
    hl.dsp.exec_cmd(terminal)
)

-- SUPER + C
hl.bind(
    mainMod .. " + C",
    hl.dsp.window.close()
)

-- SUPER + B
hl.bind(
    mainMod .. " + B",
    hl.dsp.exec_cmd(browser)
)

-- SUPER + M
hl.bind(
    mainMod .. " + M",
    hl.dsp.exec_cmd("hyprctl dispatch exit")
)

-- SUPER + E
hl.bind(
    mainMod .. " + E",
    hl.dsp.exec_cmd(fileManager)
)

-- SUPER + V
hl.bind(
    mainMod .. " + V",
    hl.dsp.window.float({
        action = "toggle",
    })
)

-- SUPER + R
hl.bind(
    mainMod .. " + R",
    hl.dsp.exec_cmd(menu)
)

-- SUPER + P
-- Toggle pseudotiling
hl.bind(
    mainMod .. " + P",
    hl.dsp.window.pseudo()
)

-- SUPER + J
-- Toggle Dwindle split direction
hl.bind(
    mainMod .. " + J",
    hl.dsp.layout("togglesplit")
)

--------------------
---- SCREENSHOT ----
--------------------

-- Print Screen
hl.bind(
    "Print",
    hl.dsp.exec_cmd(
        'grim -g "$(slurp -d)" - | wl-copy'
    )
)

-------------------------
---- WINDOW FOCUS -------
-------------------------

-- SUPER + SHIFT + LEFT
hl.bind(
    mainMod .. " + SHIFT + left",
    hl.dsp.focus({
        direction = "left",
    })
)

-- SUPER + SHIFT + RIGHT
hl.bind(
    mainMod .. " + SHIFT + right",
    hl.dsp.focus({
        direction = "right",
    })
)

-- SUPER + SHIFT + UP
hl.bind(
    mainMod .. " + SHIFT + up",
    hl.dsp.focus({
        direction = "up",
    })
)

-- SUPER + SHIFT + DOWN
hl.bind(
    mainMod .. " + SHIFT + down",
    hl.dsp.focus({
        direction = "down",
    })
)

-----------------------
---- WORKSPACES -------
-----------------------

for i = 1, 10 do

    -- Workspace 10 uses key 0
    local key = i % 10

    -- SUPER + [0-9]
    hl.bind(
        mainMod .. " + " .. key,
        hl.dsp.focus({
            workspace = i,
        })
    )

    -- SUPER + SHIFT + [0-9]
    hl.bind(
        mainMod .. " + SHIFT + " .. key,
        hl.dsp.window.move({
            workspace = i,
        })
    )
end

---------------------------
---- SPECIAL WORKSPACE ----
---------------------------

-- SUPER + S
hl.bind(
    mainMod .. " + S",
    hl.dsp.workspace.toggle_special("magic")
)

-- SUPER + SHIFT + S
hl.bind(
    mainMod .. " + SHIFT + S",
    hl.dsp.window.move({
        workspace = "special:magic",
    })
)

-------------------------------
---- EXISTING WORKSPACE SCROLL
-------------------------------

-- SUPER + RIGHT
hl.bind(
    mainMod .. " + right",
    hl.dsp.focus({
        workspace = "e+1",
    })
)

-- SUPER + LEFT
hl.bind(
    mainMod .. " + left",
    hl.dsp.focus({
        workspace = "e-1",
    })
)

------------------------------
---- MOVE / RESIZE WINDOWS ---
------------------------------

-- SUPER + Left Mouse Button
hl.bind(
    mainMod .. " + mouse:272",
    hl.dsp.window.drag(),
    {
        mouse = true,
    }
)

-- SUPER + Right Mouse Button
hl.bind(
    mainMod .. " + mouse:273",
    hl.dsp.window.resize(),
    {
        mouse = true,
    }
)

---------------------------------
---- AUDIO / BRIGHTNESS KEYS ----
---------------------------------

-- Volume Up
hl.bind(
    "XF86AudioRaiseVolume",
    hl.dsp.exec_cmd(
        "wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%+"
    ),
    {
        locked = true,
        repeating = true,
    }
)

-- Volume Down
hl.bind(
    "XF86AudioLowerVolume",
    hl.dsp.exec_cmd(
        "wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"
    ),
    {
        locked = true,
        repeating = true,
    }
)

-- Mute
hl.bind(
    "XF86AudioMute",
    hl.dsp.exec_cmd(
        "wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"
    ),
    {
        locked = true,
        repeating = true,
    }
)

-- Microphone Mute
hl.bind(
    "XF86AudioMicMute",
    hl.dsp.exec_cmd(
        "wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"
    ),
    {
        locked = true,
        repeating = true,
    }
)

----------------
-- BRIGHTNESS --
----------------

-- Brightness Up
hl.bind(
    "XF86MonBrightnessUp",
    hl.dsp.exec_cmd(
        "brightnessctl s 10%+"
    ),
    {
        locked = true,
        repeating = true,
    }
)

-- Brightness Down
hl.bind(
    "XF86MonBrightnessDown",
    hl.dsp.exec_cmd(
        "brightnessctl s 10%-"
    ),
    {
        locked = true,
        repeating = true,
    }
)

--------------------
---- MEDIA KEYS ----
--------------------

-- Next Track
hl.bind(
    "XF86AudioNext",
    hl.dsp.exec_cmd("playerctl next"),
    {
        locked = true,
    }
)

-- Pause
hl.bind(
    "XF86AudioPause",
    hl.dsp.exec_cmd("playerctl play-pause"),
    {
        locked = true,
    }
)

-- Play
hl.bind(
    "XF86AudioPlay",
    hl.dsp.exec_cmd("playerctl play-pause"),
    {
        locked = true,
    }
)

-- Previous Track
hl.bind(
    "XF86AudioPrev",
    hl.dsp.exec_cmd("playerctl previous"),
    {
        locked = true,
    }
)

--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------

-- Ignore maximize requests
hl.window_rule({
    name = "suppress-maximize-events",

    match = {
        class = ".*",
    },

    suppress_event = "maximize",
})

--------------------------------
---- XWAYLAND DRAG FIX ---------
--------------------------------

hl.window_rule({
    name = "fix-xwayland-drags",

    match = {
        class = "^$",
        title = "^$",
        xwayland = true,
        float = true,
        fullscreen = false,
        pin = false,
    },

    no_focus = true,
})